# -*- coding: utf-8 -*-
"""The style data. Everything else — the index, the per-style pages, the
plates, the search index, the sitemap entries — is derived from this list.

Each entry carries a Style DNA rather than just a name, because a name is
not reusable: "Baroque" tells a model almost nothing, while the medium,
brushwork, palette, lighting, texture, composition and mood behind it can be
recombined with any subject and with each other.

plate = (mark-making, lighting, palette) and drives the generated artwork.
  mark: impasto | dabs | wash | flat | hatch | line | smooth | grain
  lit : chiaro | golden | soft | neon | rim | flat | top | back
"""

# False while prompts/*.jpg are the code-drawn abstract plates, True once they
# are real output of each style's own prompt. Only the caption under the image
# depends on it, and that caption is a claim about what you are looking at —
# so it moves when the pictures do. plates-import.py flips it.
PLATES_ARE_SAMPLES = True

# ترتیب این فهرست هم ترتیب دکمه‌های فیلتر است و هم ترتیب گروه‌ها در صفحه.
